// ValoriaPassives.h: VALORIA's passive skill tree rules, shared by the game server
// (HG Server\Passives.cpp) and the client (Client3\UI\PassivePanel.cpp) so both always agree.
// The tree itself (301 nodes) is ValoriaPassiveTree.h, generated by tools/valoria_port/build_passives.py.
//
// Rules:
//   * Passive points: 1 per level after level 1 (139 at level 140), plus 1 per Tome of the Unbound Path read.
//   * A node can be taken when it links to a node already taken. The root is always taken and free.
//   * An Orb of Unmaking returns every point (the tree goes back to the root). Nothing else refunds.
//   * While more points are spent than the character has (after a rebirth, or in the other rebirth set),
//     the tree is kept but gives nothing until the level catches up.
//   * Active now: STR, DEX, VIT, INT, MAG, max HP, max MP, defense, damage %, max HP %, max MP %,
//     defense %, XP %. The other VALORIA modifiers are shown in the tree and come with later stages.
//
// Wire format, 48 bytes: 38 bytes of taken bits (node i = byte i/8, bit i%8), Tomes read (uint8), 9 spare.
//////////////////////////////////////////////////////////////////////

#pragma once

#include <cstdio>
#include <cstring>
#include "ValoriaPassiveTree.h"

namespace ValoriaPassive {

const int DATA_BYTES = 48;
const int BIT_BYTES  = (NODE_COUNT + 7) / 8;	// 38
const int MAX_TOMES  = 255;
const int ACTIVE_MODS = PM_XP + 1;			// PM_STR .. PM_XP work in Helbreath Reimagined now

inline const char * ModName(int k)
{
	static const char * n[PM_COUNT] = { "STR", "DEX", "VIT", "INT", "MAG", "Max HP", "Max MP", "Defense",
		"Damage", "Max HP", "Max MP", "Defense", "XP", "Crit chance", "Crit damage", "Spell damage",
		"Attack speed", "Dodge", "Move speed", "HP regen", "MP regen", "Damage taken", "Max SP", "Item find",
		"Gold find", "Boss damage", "Life steal", "Mana steal", "Thorns" };
	return (k >= 0 && k < PM_COUNT) ? n[k] : "?";
}

inline bool ModIsPercent(int k)
{
	switch (k) {
	case PM_STR: case PM_DEX: case PM_VIT: case PM_INT: case PM_MAG: case PM_HP: case PM_MP: case PM_DEF:
	case PM_REGEN: case PM_MP_REGEN: case PM_THORNS: return false;
	default: return true;
	}
}

inline bool ModActive(int k) { return k >= 0 && k < ACTIVE_MODS; }

// "+2 STR", "+3% Damage", "-8% Max HP"; damage reduction reads as "-1% Damage taken".
inline void ModText(int k, int v, char * pOut, int iSize)
{
	if (k == PM_DMG_RED) v = -v;
	_snprintf(pOut, iSize - 1, "%s%d%s %s", v >= 0 ? "+" : "", v, ModIsPercent(k) ? "%" : "", ModName(k));
	pOut[iSize - 1] = 0;
}

inline int Points(int iLevel, int iTomes) { return (iLevel > 1 ? iLevel - 1 : 0) + iTomes; }

struct Data {
	unsigned char bits[BIT_BYTES];
	unsigned char tomes;

	Data() { Clear(); }
	void Clear()				{ memset(bits, 0, sizeof(bits)); tomes = 0; bits[0] = 1; }
	void Reset()				{ memset(bits, 0, sizeof(bits)); bits[0] = 1; }	// keeps the Tomes
	bool Has(int i) const		{ return i >= 0 && i < NODE_COUNT && (bits[i >> 3] & (1 << (i & 7))) != 0; }
	void Set(int i)				{ if (i >= 0 && i < NODE_COUNT) bits[i >> 3] |= (unsigned char)(1 << (i & 7)); }
	int  Taken() const			{ int n = 0; for (int i = 1; i < NODE_COUNT; i++) if (Has(i)) n++; return n; }
	int  Spare(int iLevel) const	{ return Points(iLevel, tomes) - Taken(); }
	bool Active(int iLevel) const	{ return Spare(iLevel) >= 0; }

	bool CanTake(int i) const
	{
		if (i <= 0 || i >= NODE_COUNT || Has(i)) return false;
		for (int l = 0; l < NODES[i].links; l++) if (Has(NODES[i].link[l])) return true;
		return false;
	}

	// Every taken node can be reached from the root through taken nodes.
	bool Connected() const
	{
		unsigned char seen[BIT_BYTES] = {};
		int stack[NODE_COUNT], top = 0;
		stack[top++] = 0; seen[0] = 1;
		while (top > 0) {
			const int n = stack[--top];
			for (int l = 0; l < NODES[n].links; l++) {
				const int m = NODES[n].link[l];
				if (Has(m) && !(seen[m >> 3] & (1 << (m & 7)))) { seen[m >> 3] |= (unsigned char)(1 << (m & 7)); stack[top++] = m; }
			}
		}
		return memcmp(seen, bits, sizeof(bits)) == 0;
	}

	// Sum of every taken node's modifiers (whether or not the tree is active).
	void Totals(int * pOut) const
	{
		memset(pOut, 0, sizeof(int) * PM_COUNT);
		for (int i = 0; i < NODE_COUNT; i++) {
			if (!Has(i)) continue;
			for (int m = 0; m < NODES[i].mods; m++) pOut[NODES[i].mod[m]] += NODES[i].val[m];
		}
	}

	void Write(unsigned char * p) const
	{
		memset(p, 0, DATA_BYTES);
		memcpy(p, bits, BIT_BYTES);
		p[BIT_BYTES] = tomes;
	}
	// Reads saved data. A tree that doesn't hang together (an older tree file, a damaged save) goes back
	// to the root, so every point is returned; Tomes read are kept.
	void Read(const unsigned char * p)
	{
		memcpy(bits, p, BIT_BYTES);
		tomes = p[BIT_BYTES];
		bits[BIT_BYTES - 1] &= (unsigned char)((1 << (NODE_COUNT - (BIT_BYTES - 1) * 8)) - 1);
		bits[0] |= 1;
		if (!Connected()) Reset();
	}
};

}	// namespace ValoriaPassive
